BEGIN TRANSACTION;
CREATE TABLE clientes_preprocessados (
    id_cliente TEXT PRIMARY KEY,
    nome TEXT,
    cidade TEXT,
    uf TEXT,
    idade INTEGER,
    renda_mensal REAL,
    tempo_cliente_meses INTEGER,
    compras_12m INTEGER,
    ticket_medio REAL,
    dias_desde_ultima_compra INTEGER,
    categoria_cliente TEXT,
    categoria_cliente_cod INTEGER,
    idade_pad REAL,
    renda_mensal_pad REAL,
    tempo_cliente_meses_pad REAL,
    compras_12m_pad REAL,
    ticket_medio_pad REAL,
    dias_desde_ultima_compra_pad REAL,
    categoria_cliente_cod_pad REAL,
    componente_1 REAL,
    componente_2 REAL,
    idade_imputado INTEGER,
    renda_mensal_imputado INTEGER,
    ticket_medio_imputado INTEGER,
    categoria_imputada INTEGER,
    idade_outlier INTEGER,
    renda_mensal_outlier INTEGER,
    ticket_medio_outlier INTEGER
);
CREATE TABLE pca_variancia_explicada (
    componente INTEGER PRIMARY KEY,
    variancia_explicada REAL,
    variancia_acumulada REAL);
COMMIT;
